// Junta las respuestas de Prometheus en una tabla y detecta anomalías con reglas fijas.
// Esta parte NO usa IA: los números y las anomalías salen de comparar contra umbrales.
const lista = $('Lista de métricas').all();
const respuestas = $input.all();

const filas = lista.map((m, i) => {
  const r = (respuestas[i] && respuestas[i].json) || {};
  let valor = null;
  try {
    const crudo = r.data.result[0].value[1];
    const n = Number(crudo);
    if (Number.isFinite(n)) valor = Math.round(n * 100) / 100;
  } catch (e) { /* sin datos */ }

  let estado = 'normal';
  if (valor === null) estado = 'sin datos';
  else if (m.json.sentido === 'max' && valor > m.json.umbral) estado = 'anomalía';
  else if (m.json.sentido === 'min' && valor < m.json.umbral) estado = 'anomalía';

  return {
    clave: m.json.clave, nombre: m.json.nombre, valor, unidad: m.json.unidad,
    umbral: (m.json.sentido === 'max' ? 'hasta ' : 'desde ') + m.json.umbral + m.json.unidad,
    estado,
  };
});

const conDatos = filas.filter((x) => x.valor !== null).length;
const anomalias = filas.filter((x) => x.estado !== 'normal');
const fecha = $now.setZone('America/Argentina/Jujuy');

// Lo único que ve la IA: la tabla de arriba. Ningún dato personal ni clave.
const datosParaIA = filas.map((x) =>
  '- ' + x.nombre + ': ' + (x.valor === null ? 'sin datos' : x.valor + x.unidad)
  + ' (aceptable: ' + x.umbral + ') -> ' + x.estado).join('\n');

const instrucciones = [
  'Sos un analista de infraestructura de un sistema de reservas de hoteles.',
  'Vas a recibir una lista de métricas ya medidas, cada una con su valor, su rango aceptable y su estado.',
  'Reglas estrictas:',
  '1. Usá SOLO los datos de la lista. No inventes valores, causas, servicios ni fechas que no estén ahí.',
  '2. No cambies el estado de ninguna métrica: ya viene calculado.',
  '3. Si todas están en "normal", decilo en una oración y no busques problemas donde no los hay.',
  '4. Para cada métrica en "anomalía" o "sin datos": explicá en una línea qué significa y proponé UNA acción concreta de revisión.',
  '5. Si un dato no alcanza para sacar una conclusión, escribí "no se puede concluir con estos datos".',
  '6. Respondé en español, en texto plano, en no más de 12 líneas, sin títulos ni markdown.',
].join('\n');

return [{
  json: {
    sinDatos: conDatos === 0,
    motivo: conDatos === 0 ? 'Prometheus no devolvió ninguna métrica (¿está levantado el monitoreo?)' : null,
    fecha: fecha.toFormat('dd/MM/yyyy HH:mm'),
    sello: fecha.toFormat('yyyy-MM-dd_HHmm'),
    filas,
    anomalias,
    cuerpoIA: {
      systemInstruction: { parts: [{ text: instrucciones }] },
      contents: [{ role: 'user', parts: [{ text: 'Métricas del ' + fecha.toFormat('dd/MM/yyyy HH:mm') + ':\n' + datosParaIA }] }],
      generationConfig: { temperature: 0.2, maxOutputTokens: 1024 },
    },
  },
}];

// Arma el informe. Los números van SIEMPRE (salen de Prometheus). El texto de la IA
// va aparte y marcado como interpretación. Si la IA falló, el informe sale igual.
const base = $('Organizar métricas').first().json;
const r = $input.first().json || {};

let analisis = null;
try {
  analisis = r.candidates[0].content.parts.map((p) => p.text || '').join('').trim() || null;
} catch (e) { /* la IA no respondió */ }

let motivoIA = null;
if (!analisis) {
  const err = r.error;
  motivoIA = (err && (err.message || (typeof err === 'string' ? err : JSON.stringify(err)))) || 'La IA no devolvió texto';
  // Si el proveedor devolvió un JSON de error, quedarse solo con su mensaje.
  const texto = String(motivoIA).split('\\n').join(' ').split('\\"').join('"');
  const corto = texto.match(/"message":\s*"([^"]+)"/);
  motivoIA = (corto ? corto[1] : texto).slice(0, 300);
}

const esc = (t) => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const mostrar = (x) => (x.valor === null ? 'sin datos' : x.valor + x.unidad);

// --- Markdown (lo que se guarda en Nextcloud) ---
const md = [];
md.push('# Informe de rendimiento - Sistema de reservas de hoteles');
md.push('');
md.push('Fecha: ' + base.fecha + ' (hora de Jujuy)');
md.push('');
md.push('## 1. Métricas medidas (fuente: Prometheus)');
md.push('');
md.push('| Métrica | Valor | Aceptable | Estado |');
md.push('|---|---|---|---|');
for (const x of base.filas) md.push('| ' + x.nombre + ' | ' + mostrar(x) + ' | ' + x.umbral + ' | ' + x.estado + ' |');
md.push('');
md.push('## 2. Anomalías detectadas por reglas');
md.push('');
if (base.anomalias.length === 0) md.push('Ninguna: todas las métricas están dentro del rango aceptable.');
else for (const x of base.anomalias) md.push('- ' + x.nombre + ': ' + mostrar(x) + ' (aceptable: ' + x.umbral + ')');
md.push('');
md.push('## 3. Análisis de la IA');
md.push('');
md.push(analisis ? analisis : 'No disponible en este informe. Motivo: ' + motivoIA);
md.push('');
md.push('---');
md.push('Los puntos 1 y 2 son datos medidos y reglas fijas. El punto 3 es una interpretación hecha por un modelo de IA '
      + 'que solo recibió la tabla del punto 1; no reemplaza la revisión de una persona.');

// --- HTML (lo que va en el mail) ---
const color = { normal: '#1b5e20', 'anomalía': '#b00020', 'sin datos': '#e65100' };
let html = '<h2>Informe de rendimiento - ' + esc(base.fecha) + '</h2>';
html += '<h3>1. Métricas medidas (fuente: Prometheus)</h3>';
html += '<table cellpadding="6" border="1" style="border-collapse:collapse">';
html += '<tr><th>Métrica</th><th>Valor</th><th>Aceptable</th><th>Estado</th></tr>';
for (const x of base.filas) {
  html += '<tr><td>' + esc(x.nombre) + '</td><td>' + esc(mostrar(x)) + '</td><td>' + esc(x.umbral)
        + '</td><td style="color:' + color[x.estado] + '"><b>' + esc(x.estado) + '</b></td></tr>';
}
html += '</table>';
html += '<h3>2. Anomalías detectadas por reglas</h3>';
html += base.anomalias.length === 0
  ? '<p>Ninguna: todas las métricas están dentro del rango aceptable.</p>'
  : '<ul>' + base.anomalias.map((x) => '<li>' + esc(x.nombre) + ': ' + esc(mostrar(x)) + '</li>').join('') + '</ul>';
html += '<h3>3. Análisis de la IA</h3>';
html += analisis
  ? '<p>' + esc(analisis).replace(/\n/g, '<br>') + '</p>'
  : '<p><i>No disponible en este informe. Motivo: ' + esc(motivoIA) + '</i></p>';
html += '<hr><p style="color:#555;font-size:12px">Los puntos 1 y 2 son datos medidos y reglas fijas. '
      + 'El punto 3 es una interpretación de un modelo de IA que solo recibió la tabla del punto 1.</p>';

return [{
  json: {
    fecha: base.fecha,
    nombreArchivo: 'informe_rendimiento_' + base.sello + '.md',
    informeMd: md.join('\n'),
    informeHtml: html,
    filas: base.filas,
    anomalias: base.anomalias,
    usoIA: !!analisis,
    motivoIA,
  },
}];

// Si Nextcloud no está configurado o falló, el informe queda en la tabla local.
// En los dos casos se guarda en la base y se manda por mail: nunca se pierde.
const cfg = $('Configuración').first().json;
const inf = $('Armar informe').first().json;
const r = $input.first().json || {};

const configurado = !!cfg.nextcloudUrl;
const fallo = configurado && r.error ? String(r.error.message || (typeof r.error === 'string' ? r.error : JSON.stringify(r.error))).slice(0, 300) : null;
const destino = configurado && !fallo ? 'nextcloud' : 'local';
const ruta = destino === 'nextcloud' ? cfg.nextcloudCarpeta + '/' + inf.nombreArchivo : 'tabla informes_rendimiento';

const errores = [];
if (!inf.usoIA) errores.push({ tarea: 'Analizar con IA (Gemini)', detalle: inf.motivoIA });
if (fallo) errores.push({ tarea: 'Subir a Nextcloud', detalle: fallo });

return [{
  json: {
    ...inf,
    destino,
    ruta,
    falloNextcloud: fallo,
    paraBase: JSON.stringify({
      metricas: inf.filas, anomalias: inf.anomalias, uso_ia: inf.usoIA, modelo: inf.usoIA ? cfg.geminiModelo : null,
      destino, ruta, contenido: inf.informeMd, ejecucion_n8n: $execution.id,
    }),
    paraErrores: JSON.stringify({ ejecucion: $execution.id, errores }),
  },
}];
